<script setup lang="ts">import {computed,ref} from 'vue';import {Result,CurvePoint,GroupResult} from '../types/domain';import {percent} from '../utils/format';const props=defineProps<{result:Result}>();const bands=ref(true),boot=ref(false);const maximum=computed(()=>Math.max(1200,...props.result.groups.map(g=>g.last_observed)));const x=(v:number)=>65+v/maximum.value*815,y=(v:number)=>235-v*200;function step(points:CurvePoint[],key:'survival'|'lower'|'upper'){let d=`M${x(0)},${y(1)}`;for(const p of points.slice(1))d+=`H${x(p.time)}V${y(p[key])}`;return d}function area(points:CurvePoint[]){let d=step(points,'upper');const last=points[points.length-1];d+=`L${x(last.time)},${y(last.lower)}`;for(let i=points.length-1;i>0;i--){d+=`V${y(points[i-1].lower)}H${x(points[i-1].time)}`}return d+'Z'}function bootPoints(g:GroupResult):CurvePoint[]{const b=(props.result.bootstrap?.groups||[]).find(x=>x.cohort_id===g.cohort.id);if(!b)return[];return b.band.time.map((t,i)=>({time:t,lower:b.band.lower[i],upper:b.band.upper[i]}) as CurvePoint)}</script><template><section class="survival-plot"><div class="plot-toolbar"><h3>仍保持工作状态的概率</h3><div class="plot-toggles"><button :class="{active:bands}" @click="bands=!bands">{{Math.round(result.confidence*100)}}% 逐点区间 {{bands?'显示中':'已隐藏'}}</button><button v-if="result.bootstrap" :class="{active:boot}" @click="boot=!boot">整卷重抽样带 {{boot?'显示中':'已隐藏'}}</button></div></div><svg viewBox="0 0 940 280" aria-label="Kaplan-Meier耐久曲线"><g v-for="v in [0,.25,.5,.75,1]" :key="v"><line x1="65" x2="880" :y1="y(v)" :y2="y(v)" class="gridline"/><text x="54" :y="y(v)+4" text-anchor="end">{{percent(v)}}</text></g><g v-for="(g,i) in result.groups" :key="g.cohort.id" :class="'curve-'+i"><path v-if="boot&&bootPoints(g).length>1" :d="area(bootPoints(g))" class="bootstrap-band"/><path v-if="bands" :d="area(g.curve)" class="confidence-band"/><path :d="step(g.curve,'survival')" class="survival-line"/><g v-for="p in g.curve.filter(p=>p.censored>0)" :key="p.time"><line :x1="x(p.time)" :x2="x(p.time)" :y1="y(p.survival)-4" :y2="y(p.survival)+4" class="censor-mark"/></g></g><text v-for="v in [0,400,800,1200]" :key="v" :x="x(v)" y="258" text-anchor="middle">{{v}}</text><text x="885" y="258">小时</text></svg><div class="plot-legend"><span v-for="(g,i) in result.groups" :key="g.cohort.id" :class="'legend-'+i"><i/>{{g.cohort.name}}</span><small>短竖线为删失 · 阶梯在失效事件处下降<template v-if="result.bootstrap&&boot"> · 虚线带为整卷重抽样区间</template></small></div></section></template>
